              (a, b) =>
                Number(a.total_amount) - Number(b.total_amount) ||
                a.flight_id.localeCompare(b.flight_id) ||
                a.supplier.localeCompare(b.supplier),
            );
          });
          end = buffer.indexOf("\n");
        }
      }
