                          and(eq(event.stream, "public"), gt(event.revision, cursor.public)),
                          cursor.private
                            ? and(
                                eq(event.stream, cursor.private.accountId),
                                gt(event.revision, cursor.private.revision),
                              )
                            : undefined,
                        ),
                      )
                      .orderBy(asc(event.stream), asc(event.revision))
                      .limit(100);
                    await Promise.resolve().then(async () => {
                      const replayWake = notifications.revision();
                      if (replayWake === authorizedWake) return;
                      const current = await account.run();
                      authorizedWake = replayWake;
                      if (ended) return;
                      if (current !== expectedAccount) {
                        output?.enqueue(
                          encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n'),
                        );
                        close();
                      }
                    });
                    if (ended) return true;
                    if (!rows.length) {
                      afterWake = wake;
                      return false;
                    }
                    for (const row of rows) {
                      if (row.stream === "public") cursor.public = row.revision;
                      else if (cursor.private) cursor.private.revision = row.revision;
                    }
                    controller.enqueue(
                      encoder.encode(
                        `event: changes\nid: ${JSON.stringify(cursor)}\ndata: ${JSON.stringify({ kind: "changes", events: rows })}\n\n`,
                      ),
                    );
                    return true;
                  });
                  if (replayed) return;
                  const delivered = await Promise.resolve().then(async () => {
                    if (ended || notifications.revision() !== afterWake) return false;
                    if (!greeted) {
                      greeted = true;
                      controller.enqueue(encoder.encode(": connected\n\n"));
                      return true;
                    }
                    const waiting = new AbortController();
                    const waitingSignal = AbortSignal.any([signal, waiting.signal]);
                    try {
                      const outcome = await Promise.race([
                        notifications.wait(changes, afterWake, waitingSignal).then(() => "changed"),
                        ctx.clock.sleep(10_000, waitingSignal).then(() => "heartbeat"),
                      ]);
                      if (outcome !== "heartbeat") return false;
                      await Promise.resolve().then(async () => {
                        const heartbeatWake = notifications.revision();
                        const current = await account.run();
                        authorizedWake = heartbeatWake;
                        if (ended) return;
                        if (current !== expectedAccount) {
                          output?.enqueue(
                            encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n'),
                          );
                          close();
                        }
                      });
                      await Promise.resolve().then(async () => {
                        if (ended) return;
                        const latestWake = notifications.revision();
                        if (latestWake === authorizedWake) return;
                        const latestAccount = await account.run();
                        authorizedWake = latestWake;
                        if (ended) return;
                        if (latestAccount !== expectedAccount) {
                          output?.enqueue(
                            encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n'),
                          );
                          close();
                        }
                      });
                      if (!ended) controller.enqueue(encoder.encode(": heartbeat\n\n"));
                      return true;
                    } finally {
                      waiting.abort();
                    }
                  });
                  if (delivered) return;
                }
              } catch (error) {
                if (signal.aborted) {
                  close();
                  return;
                }
                ended = true;
                stop.abort();
                notifications.close(changes);
                controller.error(error);
              }
            },
            cancel() {
              output = undefined;
              close();
            },
          },
          { highWaterMark: 0 },
        );
        return new Response(body, {
          headers: {
            "Content-Type": "text/event-stream; charset=utf-8",
            "Cache-Control": "no-store",
            "X-Accel-Buffering": "no",
          },
        });
      },
    };
  },
})

snapshotLoader = resource({
  label: "sync.snapshotLoader",
  depends: { sync: syncClient, apply: applyBootstrap, source: snapshotSource },
  factory: async ({ sync, apply, source }) => {
    let loadedVersion = -1;
    let loading: { version: number; promise: Promise<Sync.Snapshot> } | undefined;
    let changing: ReturnType<typeof Promise.withResolvers<void>> | undefined;
    return {
      beginAccountChange() {
        changing = Promise.withResolvers<void>();
        return changing;
      },
      endAccountChange(change: ReturnType<typeof Promise.withResolvers<void>>) {
        if (changing === change) changing = undefined;
        change.resolve();
      },
      async completeAccountChange(
        signal: AbortSignal,
        change: ReturnType<typeof Promise.withResolvers<void>>,
      ) {
        try {
          const token = sync.capture();
          if (loadedVersion === token.version) return sync.snapshot();
          if (loading?.version === token.version) return loading.promise;
          const request = {
            version: token.version,
            promise: Promise.resolve().then(async () => {
              const snapshot = await source.load({ signal });
              const version = await apply.run({ rawInput: { snapshot, version: token.version } });
              if (version !== undefined) loadedVersion = version;
              return sync.snapshot();
            }),
          };
          loading = request;
          try {
            return await request.promise;
          } finally {
            if (loading === request) loading = undefined;
          }
        } finally {
          if (changing === change) changing = undefined;
          change.resolve();
        }
      },
      async ready() {
        await changing?.promise;
      },
      async account(signal: AbortSignal) {
        await changing?.promise;
        const accountId = await source.account({ signal });
        if (accountId !== sync.cursors().accountId) sync.leave();
        return accountId;
      },
      async load(signal: AbortSignal) {
        await changing?.promise;
        const token = sync.capture();
        if (loadedVersion === token.version) return sync.snapshot();
        if (loading?.version === token.version) return loading.promise;
        const request = {
          version: token.version,
          promise: Promise.resolve().then(async () => {
            const snapshot = await source.load({ signal });
            const version = await apply.run({ rawInput: { snapshot, version: token.version } });
            if (version !== undefined) loadedVersion = version;
            return sync.snapshot();
          }),
        };
        loading = request;
        try {
          return await request.promise;
        } finally {
          if (loading === request) loading = undefined;
        }
      },
    };
  },
})

eventSource = resource({
  label: "sync.eventSource",
  factory: (_deps, ctx) => {
    let close: (() => void) | undefined;
    ctx.defer(() => close?.());
    let source: EventSource | undefined;
    let signal: AbortSignal | undefined;
    const queue: string[] = [];
    let ended = true;
    let waiting: ReturnType<typeof Promise.withResolvers<void>> | undefined;
    return {
      connect(cursor: Stream.Cursor, stop: AbortSignal) {
        close?.();
        signal = stop;
        source = new EventSource(`/api/sync?cursor=${encodeURIComponent(JSON.stringify(cursor))}`);
        ended = false;
        const connection = source;
        const connectionSignal = signal;
        const closeConnection = () => {
          if (ended) return;
          ended = true;
          connection.close();
          queue.length = 0;
          connectionSignal.removeEventListener("abort", closeConnection);
          waiting?.resolve();
        };
        close = closeConnection;
        const receive = (event: MessageEvent<string>) => {
          if (ended) return;
          if (queue.length >= 8) {
            closeConnection();
            return;
          }
          queue.push(event.data);
          waiting?.resolve();
        };
        source.addEventListener("changes", receive);
        source.addEventListener("account", receive);
        source.addEventListener("error", closeConnection);
        signal.addEventListener("abort", closeConnection, { once: true });
        if (signal.aborted) closeConnection();
      },
      close() {
        close?.();
      },
      async next() {
        while (!ended && queue.length === 0) {
          const received = Promise.withResolvers<void>();
          waiting = received;
          await received.promise;
          waiting = undefined;
        }
        return ended ? undefined : queue.shift();
      },
    };
  },
})

syncClient = resource({
  label: "sync.client",
  depends: { owner: accountOwner, records },
  factory: async ({ owner, records }, ctx) => {
    let accountId: string | null = null;
    const cursors = new Map<string, number>();
    cursors.set("public", -1);
    const local = new Set<string>();
    const results = new Map<string, Sync.Result>();
    const waiters = new Map<string, ReturnType<typeof Promise.withResolvers<Sync.Result>>>();
    ctx.defer(() => {
      for (const waiting of waiters.values()) waiting.reject(fail("Cancelled", {}));
      waiters.clear();
      results.clear();
      local.clear();
    });
    const client = {
      capture: owner.capture,
      cursors: () => ({
        accountId,
        publicRevision: cursors.get("public") ?? -1,
        privateRevision: accountId === null ? -1 : (cursors.get(accountId) ?? -1),
      }),
      snapshot: () =>
        records.snapshot(
          cursors.get("public") ?? -1,
          accountId === null ? -1 : (cursors.get(accountId) ?? -1),
        ),
      leave() {
        owner.reset();
        if (accountId !== null) cursors.delete(accountId);
        accountId = null;
        records.resetPrivate();
        for (const waiting of waiters.values()) waiting.reject(fail("Cancelled", {}));
        waiters.clear();
        results.clear();
        local.clear();
      },
      bootstrap(snapshot: Sync.Snapshot, version: number) {
        if (version !== owner.capture().version) return;
        const nextId = snapshot.private?.stream ?? null;
        if (nextId !== accountId) client.leave();
        if (local.size > 0) return;
        accountId = nextId;
        client.merge(snapshot);
        return owner.capture().version;
      },
      merge(snapshot: Sync.Snapshot) {
        const publicRevision = cursors.get("public") ?? -1;
        records.bootstrapPublic(snapshot.public, publicRevision);
        cursors.set("public", Math.max(publicRevision, snapshot.public.revision));
        if (snapshot.private) {
          const privateRevision = cursors.get(snapshot.private.stream) ?? -1;
          records.bootstrapPrivate(snapshot.private, privateRevision);
          cursors.set(
            snapshot.private.stream,
            Math.max(privateRevision, snapshot.private.revision),
          );
        }
      },
      finish(executionId: string, result: Sync.Result) {
        if (!local.has(executionId)) return;
        results.set(executionId, result);
        waiters.get(executionId)?.resolve(result);
      },
      apply(events: Sync.Event[], version: number) {
        if (version !== owner.capture().version) return;
        for (const event of events) {
          const previous = cursors.get(event.stream);
          if (previous === undefined || event.revision <= previous) continue;
          if (event.revision !== previous + 1) break;
          if (event.payload.kind === "change") records.change(event.payload.change);
          else client.finish(event.executionId, event.payload.result);
          cursors.set(event.stream, event.revision);
        }
      },
      async wait(executionId: string, version: number, signal: AbortSignal): Promise<Sync.Result> {
        if (version !== owner.capture().version || signal.aborted) raise("Cancelled", {});
        const completed = results.get(executionId);
        if (completed) return completed;
        const waiting = Promise.withResolvers<Sync.Result>();
        waiters.set(executionId, waiting);
        const stop = () => waiting.reject(fail("Cancelled", {}));
        signal.addEventListener("abort", stop, { once: true });
        try {
          return await waiting.promise;
        } finally {
          signal.removeEventListener("abort", stop);
          waiters.delete(executionId);
        }
      },
      async execute<T>(
        executionId: string,
        request: {
          data: T;
          send: (options: { data: T; signal: AbortSignal }) => Promise<Sync.Reply>;
        },
        callSignal: AbortSignal,
      ): Promise<Sync.Result> {
        const token = owner.capture();
        const signal = AbortSignal.any([token.signal, callSignal]);
        local.add(executionId);
        try {
          for (;;) {
            if (signal.aborted) raise("Cancelled", {});
            let reply: Sync.Reply;
            try {
              reply = await request.send({ data: request.data, signal });
            } catch (error) {
              if (signal.aborted) throw error;
              ctx.log("sync.reconnecting");
              await ctx.clock.sleep(500, signal);
              continue;
            }
            if (reply.kind === "rejected") raise("WriteRejected", { message: reply.message });
            const result = await client.wait(executionId, token.version, signal);
            if (signal.aborted) raise("Cancelled", {});
            return result;
          }
        } finally {
          local.delete(executionId);
          results.delete(executionId);
        }
      },
    };
    return client;
  },
})

delivery = resource({
  label: "telemetry.delivery",
  depends: { settings: telemetrySettings.required },
  factory: ({ settings }) => {
    const send = createIsomorphicFn()
      .server(async (batch: Telemetry.Batch, signal: AbortSignal): Promise<Telemetry.Delivery> => {
        if (settings.side === "browser") return { traces: true, logs: true };
        const logs = new URL(settings.logs);
        logs.searchParams.set("_time_field", "time");
        logs.searchParams.set("_msg_field", "msg");
        logs.searchParams.set("_stream_fields", "service,side");
        const [tracesAccepted, logsAccepted] = await Promise.all([
          batch.traces.length === 0
            ? true
            : Promise.resolve().then(async () => {
                try {
                  const response = await fetch(settings.traces, {
                    method: "POST",
                    headers: { "content-type": "application/json" },
                    signal,
                    redirect: "error",
                    body: JSON.stringify({
                      resourceSpans: ["server", "browser", "ssr"].flatMap((side) => {
                        const spans = batch.traces
                          .filter((span) => span.side === side)
                          .map(({ side: _side, ...span }) => span);
                        return spans.length
                          ? [
                              {
                                resource: {
                                  attributes: [
                                    {
                                      key: "service.name",
                                      value: { stringValue: settings.service },
                                    },
                                    { key: "tinker.side", value: { stringValue: side } },
                                  ],
                                },
                                scopeSpans: [{ scope: { name: "tinker.start" }, spans }],
                              },
                            ]
                          : [];
                      }),
                    }),
                  });
                  await response.body?.cancel();
                  return response.ok;
                } catch {
                  return false;
                }
              }),
          batch.logs.length === 0
            ? true
            : Promise.resolve().then(async () => {
                try {
                  const response = await fetch(logs.href, {
                    method: "POST",
                    headers: { "content-type": "application/stream+json" },
                    signal,
                    redirect: "error",
                    body: batch.logs.map((record) => JSON.stringify(record)).join("\n"),
                  });
                  await response.body?.cancel();
                  return response.ok;
                } catch {
                  return false;
                }
              }),
        ]);
        return { traces: tracesAccepted, logs: logsAccepted };
      })
      .client(async (batch: Telemetry.Batch, signal: AbortSignal): Promise<Telemetry.Delivery> => {
        try {
          const response = await fetch("/api/telemetry", {
            method: "POST",
            credentials: "same-origin",
            headers: { "content-type": "application/json" },
            body: JSON.stringify(batch),
            signal,
            keepalive: true,
            redirect: "error",
          });
          await response.body?.cancel();
          return { traces: response.ok, logs: response.ok };
        } catch {
          return { traces: false, logs: false };
        }
      });
    return { send };
  },
})

queue = resource({
  label: "telemetry.queue",
  target: "scope",
  depends: { settings: telemetrySettings.required, health: exportHealth.controller, delivery },
  factory: ({ settings, health, delivery }, ctx) => {
    let records: (
      | { kind: "trace"; value: Telemetry.Span }
      | { kind: "log"; value: Telemetry.Log }
    )[] = [];
    let queueBytes = 0;
    let dropped = 0;
    let timer: Promise<void> | undefined;
    let pending: Promise<void> | undefined;
    const stopTimer = new AbortController();
    const stopRequests = new AbortController();
    let state: "open" | "closing" | "closed" = "open";
    let publishing = true;
    let failed = false;
    const owned = {
      ingest(batch: Telemetry.Batch) {
        const incoming: typeof records = [
          ...batch.traces.map((value) => ({ kind: "trace" as const, value })),
          ...batch.logs.map((value) => ({ kind: "log" as const, value })),
        ];
        for (const record of incoming) {
          const recordBytes = new TextEncoder().encode(JSON.stringify(record.value)).byteLength;
          if (
            [
              state === "closed",
              recordBytes > 48_000,
              records.length >= 512,
              queueBytes + recordBytes > 1_048_576,
            ].includes(true)
          ) {
            dropped++;
          } else {
            records.push(record);
            queueBytes += recordBytes;
          }
          if (publishing) {
            const previous = health.get();
            health.set(
              previous.kind === "failed"
                ? { ...previous, pending: records.length, dropped }
                : { kind: pending ? "sending" : "queued", pending: records.length, dropped },
            );
          }
        }
      },
      start(flush: () => Promise<void>) {
        if (settings.side !== "ssr")
          timer = Promise.resolve().then(async () => {
            while (!stopTimer.signal.aborted) {
              try {
                await ctx.clock.sleep(1000, stopTimer.signal);
              } catch (error) {
                if (!stopTimer.signal.aborted) throw error;
                return;
              }
              if (!stopTimer.signal.aborted) await flush();
            }
          });
      },
      flush(): Promise<void> {
        return (pending ??= Promise.resolve()
          .then(async () => {
            if (state === "closed" || !records.length) return;
            let bytes = 0;
            const retained = records.filter((record, index) => {
              const size = new TextEncoder().encode(JSON.stringify(record.value)).byteLength;
              if (index >= 64 || bytes + size > 48_000) return false;
              bytes += size;
              return true;
            });
            const batch: Telemetry.Batch = {
              traces: retained
                .filter((record) => record.kind === "trace")
                .map((record) => record.value),
              logs: retained
                .filter((record) => record.kind === "log")
                .map((record) => record.value),
            };
            if (publishing)
              health.set({ kind: "sending", pending: records.length, dropped: dropped });
            const request = new AbortController();
            const deadline = new AbortController();
            const alarm = Promise.resolve().then(async () => {
              try {
                await ctx.clock.sleep(750, deadline.signal);
                request.abort();
              } catch (error) {
                if (!deadline.signal.aborted) throw error;
              }
            });
            let result: Telemetry.Delivery;
            try {
              result = await delivery.send(
                batch,
                AbortSignal.any([request.signal, stopRequests.signal]),
              );
            } finally {
              deadline.abort();
              await alarm;
            }
            const accepted = new Set(
              retained.filter((record) => (record.kind === "trace" ? result.traces : result.logs)),
            );
            records = records.filter((record) => !accepted.has(record));
            queueBytes = records.reduce(
              (sum, record) =>
                sum + new TextEncoder().encode(JSON.stringify(record.value)).byteLength,
              0,
            );
            failed = !result.traces || !result.logs;
            if (publishing)
              health.set(
                !failed
                  ? {
                      kind: records.length ? "queued" : "idle",
                      pending: records.length,
                      dropped: dropped,
                    }
                  : {
                      kind: "failed",
                      failure: "Telemetry storage did not accept the batch",
                      pending: records.length,
                      dropped: dropped,
                    },
              );
          })
          .finally(() => {
            pending = undefined;
          }));
      },
      async close() {
        if (state !== "open") return;
        state = "closing";
        publishing = false;
        stopTimer.abort();
        const deadline = new AbortController();
        const alarm = Promise.resolve().then(async () => {
          try {
            await ctx.clock.sleep(1500, deadline.signal);
            stopRequests.abort();
          } catch (error) {
            if (!deadline.signal.aborted) throw error;
          }
        });
        try {
          await timer;
          while (records.length && !stopRequests.signal.aborted) {
            await owned.flush();
            if (failed) break;
          }
        } finally {
          state = "closed";
          stopRequests.abort();
          deadline.abort();
          await alarm;
          dropped += records.length;
          records = [];
          queueBytes = 0;
          if (publishing) health.set({ kind: "closed", pending: 0, dropped: dropped });
        }
      },
    };
    ctx.defer(() => owned.close());
    return owned;
  },
})

